242	struct RunPassOption {
243	  void operator=(const std::string &Val) const {
244	    if (Val.empty())
245	      return;
246	    SmallVector<StringRef, 8> PassNames;
247	    StringRef(Val).split(PassNames, ',', -1, false);
248	    for (auto PassName : PassNames)
249	      getRunPassNames().push_back(std::string(PassName));
250	  }
251	};
