297	[[noreturn]] static void reportError(Twine Msg, StringRef Filename = "") {
298	  SmallString<256> Prefix;
299	  if (!Filename.empty()) {
300	    if (Filename == "-")
301	      Filename = "<stdin>";
302	    ("'" + Twine(Filename) + "': ").toStringRef(Prefix);
303	  }
304	  WithColor::error(errs(), "llc") << Prefix << Msg << "\n";
305	  exit(1);
306	}
