308	[[noreturn]] static void reportError(Error Err, StringRef Filename) {
309	  assert(Err);
310	  handleAllErrors(createFileError(Filename, std::move(Err)),
311	                  [&](const ErrorInfoBase &EI) { reportError(EI.message()); });
312	  llvm_unreachable("reportError() should not return");
313	}
